function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function IndustrialRoboticsConcentrationDashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [ladderMetric, setLadderMetric] = useState<LadderMetric>("sharePct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [industryLens, setIndustryLens] = useState<"global" | "china">("global");

  const ladderBars = useMemo(() => {
    return [...MARKET_SHARES]
      .map((m) => ({
        ...m,
        value:
          ladderMetric === "sharePct"
            ? m.sharePct
            : ladderMetric === "units2024"
              ? m.units2024
              : m.cumulativeSharePct,
      }))
      .sort((a, b) => b.value - a.value);
  }, [ladderMetric]);

  const regionDonut = useMemo(
    () =>
      REGION_SHARES.map((r) => ({
        name: r.short,
        value: r.share2024Pct,
        fill: r.fill,
      })),
    [],
  );

  const industryBars = useMemo(() => {
    return INDUSTRY_SHARES.filter((i) => i.short !== "Other").map((i) => ({
      ...i,
      value:
        industryLens === "global"
          ? i.sharePct
          : (i.chinaGlobalSharePct ?? 0),
      label:
        industryLens === "global"
          ? `${i.sharePct}% of world`
          : i.chinaGlobalSharePct != null
            ? `China ${i.chinaGlobalSharePct}% of global ${i.short.toLowerCase()}`
            : "n/a",
    }));

#!/usr/bin/env node
/**
 * Orchestrator bless/pause/sync gate.
 *
 *   node scripts/lib/conveyor-sync.mjs --set-phase pausing --job <id> --exclude 3
 *   node scripts/lib/conveyor-sync.mjs --set-phase idle
 *   node scripts/lib/conveyor-sync.mjs --wait-idle --timeout 180
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { REPO_ROOT } from "./agent-jobs.mjs";

export const SYNC_FILE = path.join(REPO_ROOT, "artifacts", "conveyor-sync.json");
export const PAUSE_PHASES = new Set(["pausing", "merging", "syncing"]);

export function emptySync() {
  return {
    version: 1,
    phase: "idle",
    generation: 0,
    blessedJobId: null,
    blessedSlug: null,
    blessedBranch: null,
    excludeWorkerId: null,
    pausedAt: null,
    mergedAt: null,
    syncedAt: null,
    notes: null,
    acks: {},
  };
}

export function readSync() {
  try {
    const raw = fs.readFileSync(SYNC_FILE, "utf8").replace(/^\uFEFF/, "");
    const data = JSON.parse(raw);
    return { ...emptySync(), ...data };
  } catch {
    return emptySync();
  }
}

export function writeSync(patch) {
  const prev = readSync();
  const next = { ...prev, ...patch, updatedAt: new Date().toISOString() };
  if (patch.phase && patch.phase !== prev.phase) {
    next.generation = (Number(prev.generation) || 0) + 1;
  }
  fs.mkdirSync(path.dirname(SYNC_FILE), { recursive: true });

